<script lang="ts">
 import { onMount } from 'svelte';
 let commandes:any[]=[]; let fournisseurs:any[]=[]; let chantiers:any[]=[]; let search=''; let open=false; let editing:any=null; let saving=false; let message='';
 const statusLabels:any={brouillon:'Brouillon',commandee:'Commandée',recue:'Reçue',annulee:'Annulée'};
 const statusClasses:any={brouillon:'bg-slate-100 text-slate-700',commandee:'bg-blue-100 text-blue-700',recue:'bg-green-100 text-green-700',annulee:'bg-red-100 text-red-700'};
 let form:any={fournisseur_id:'',chantier_id:'',status:'brouillon',order_date:new Date().toISOString().slice(0,10),expected_date:'',notes:'',lignes:[{designation:'',quantity:1,unit:'u',unit_price_ht:0}]};
 async function load(){const [o,f,c]=await Promise.all([fetch('/api/commandes'),fetch('/api/fournisseurs'),fetch('/api/chantiers')]); const ob=await o.json(),fb=await f.json(),cb=await c.json();commandes=ob.commandes??[];fournisseurs=fb.fournisseurs??[];chantiers=cb.chantiers??[]}
 onMount(load);
 function fresh(){return {fournisseur_id:'',chantier_id:'',status:'brouillon',order_date:new Date().toISOString().slice(0,10),expected_date:'',notes:'',lignes:[{designation:'',quantity:1,unit:'u',unit_price_ht:0}]}}
 function create(){editing=null;form=fresh();message='';open=true}
 function edit(o:any){editing=o;form={fournisseur_id:o.fournisseur_id??'',chantier_id:o.chantier_id??'',status:o.status??'brouillon',order_date:o.order_date??'',expected_date:o.expected_date??'',notes:o.notes??'',lignes:(o.lignes?.length?o.lignes: [{designation:'',quantity:1,unit:'u',unit_price_ht:0}]).map((l:any)=>({...l}))};message='';open=true}
 function addLine(){form.lignes=[...form.lignes,{designation:'',quantity:1,unit:'u',unit_price_ht:0}]}
 function removeLine(i:number){if(form.lignes.length===1)return;form.lignes=form.lignes.filter((_:any,n:number)=>n!==i)}
 $: total=form.lignes.reduce((s:number,l:any)=>s+(Number(l.quantity)||0)*(Number(l.unit_price_ht)||0),0);
 $: filtered=commandes.filter(o=>`${o.fournisseurs?.name??''} ${o.chantiers?.name??''} ${o.notes??''}`.toLowerCase().includes(search.toLowerCase()));
 async function save(){message='';if(!form.fournisseur_id){message='Sélectionne un fournisseur.';return}if(!form.lignes.some((l:any)=>String(l.designation).trim())){message='Ajoute au moins une ligne de commande.';return} saving=true;const r=await fetch('/api/commandes',{method:editing?'PATCH':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(editing?{id:editing.id,...form}:{...form})});const b=await r.json();if(!r.ok){message=b.error??'Erreur';saving=false;return}open=false;saving=false;await load()}
 async function remove(o:any){if(!confirm(`Supprimer la commande de ${o.fournisseurs?.name??'ce fournisseur'} ?`))return;const r=await fetch('/api/commandes',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({id:o.id})});if(r.ok)await load()}
 const money=(n:any)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(Number(n)||0);
</script>
<svelte:head><title>ChantierBot — Commandes</title></svelte:head>
<div class="space-y-6">
 <div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-xs font-bold uppercase tracking-[.16em] text-primary">Achats</p><h1 class="text-3xl font-extrabold">Commandes</h1><p class="mt-1 text-sm text-ink-secondary dark:text-ink-dark-secondary">Crée, suis et rattache tes commandes aux chantiers.</p></div><button class="btn-primary" on:click={create}>＋ Nouvelle commande</button></div>
 <div class="grid gap-3 sm:grid-cols-3"><div class="card"><p class="text-xs font-bold uppercase text-slate-500">Total</p><p class="mt-2 text-2xl font-extrabold">{commandes.length}</p></div><div class="card"><p class="text-xs font-bold uppercase text-slate-500">À recevoir</p><p class="mt-2 text-2xl font-extrabold">{commandes.filter(o=>o.status==='commandee').length}</p></div><div class="card"><p class="text-xs font-bold uppercase text-slate-500">Montant HT</p><p class="mt-2 text-2xl font-extrabold">{money(commandes.reduce((s:number,o:any)=>s+Number(o.total_ht||0),0))}</p></div></div>
 <div class="card"><div class="mb-4 flex gap-3"><input class="input flex-1" bind:value={search} placeholder="Rechercher fournisseur, chantier…"/><span class="rounded-xl bg-primary/10 px-4 py-2 text-sm font-bold text-primary">{filtered.length}</span></div>
 {#if !filtered.length}<div class="py-12 text-center"><div class="text-4xl">📦</div><h2 class="mt-3 font-bold">Aucune commande</h2><p class="mt-1 text-sm text-ink-secondary">Crée ta première commande fournisseur.</p></div>{:else}<div class="space-y-3">{#each filtered as o}<article class="rounded-2xl border border-black/5 p-4 transition hover:border-primary/30 dark:border-white/10"><div class="flex flex-col gap-3 md:flex-row md:items-start"><div class="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-primary to-violet-500 text-xl text-white">📦</div><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><h2 class="font-bold">{o.fournisseurs?.name??'Fournisseur'}</h2><span class={`rounded-full px-2.5 py-1 text-xs font-bold ${statusClasses[o.status]??statusClasses.brouillon}`}>{statusLabels[o.status]??o.status}</span></div><p class="mt-1 text-sm text-slate-500">{o.chantiers?.name??'Aucun chantier'} · Commandée le {o.order_date}</p>{#if o.expected_date}<p class="text-sm text-slate-500">Réception prévue : {o.expected_date}</p>{/if}<div class="mt-3 grid gap-1 text-sm">{#each o.lignes??[] as l}<div class="flex justify-between gap-3"><span class="truncate">{l.designation} <span class="text-slate-400">× {l.quantity} {l.unit}</span></span><span class="font-semibold">{money(Number(l.quantity)*Number(l.unit_price_ht))}</span></div>{/each}</div></div><div class="text-left md:text-right"><p class="text-xl font-extrabold">{money(o.total_ht)}</p><div class="mt-3 flex gap-2 md:justify-end"><button class="btn-secondary" on:click={()=>edit(o)}>Modifier</button><button class="rounded-xl px-3 py-2 text-sm font-semibold text-red-600 hover:bg-red-50" on:click={()=>remove(o)}>Supprimer</button></div></div></div></article>{/each}</div>{/if}</div>
</div>
{#if open}<div class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4" on:click={(e)=>e.target===e.currentTarget&&(open=false)}><div class="max-h-[92vh] w-full max-w-3xl overflow-auto rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900"><div class="flex justify-between"><div><p class="text-xs font-bold uppercase text-primary">{editing?'Modifier':'Nouvelle'} commande</p><h2 class="text-2xl font-extrabold">Commande fournisseur</h2></div><button class="text-2xl text-slate-400" on:click={()=>open=false}>×</button></div>
 <div class="mt-5 grid gap-4 sm:grid-cols-2"><label><span class="label">Fournisseur *</span><select class="input" bind:value={form.fournisseur_id}><option value="">Sélectionner…</option>{#each fournisseurs as f}<option value={f.id}>{f.name}</option>{/each}</select></label><label><span class="label">Chantier</span><select class="input" bind:value={form.chantier_id}><option value="">Aucun</option>{#each chantiers as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label><span class="label">Statut</span><select class="input" bind:value={form.status}>{#each Object.entries(statusLabels) as [v,l]}<option value={v}>{l}</option>{/each}</select></label><label><span class="label">Date de commande</span><input class="input" type="date" bind:value={form.order_date}/></label><label><span class="label">Réception prévue</span><input class="input" type="date" bind:value={form.expected_date}/></label></div>
 <div class="mt-6"><div class="mb-3 flex items-center justify-between"><h3 class="font-bold">Lignes de commande</h3><button class="btn-secondary text-sm" on:click={addLine}>＋ Ajouter une ligne</button></div><div class="space-y-3">{#each form.lignes as line,i}<div class="grid gap-2 rounded-xl border border-slate-200 p-3 dark:border-slate-700 sm:grid-cols-[1fr_90px_80px_120px_40px]"><input class="input" placeholder="Désignation" bind:value={line.designation}/><input class="input" type="number" min="0.001" step="0.001" bind:value={line.quantity}/><input class="input" placeholder="Unité" bind:value={line.unit}/><input class="input" type="number" min="0" step="0.01" placeholder="Prix HT" bind:value={line.unit_price_ht}/><button class="rounded-lg text-red-500 hover:bg-red-50 disabled:opacity-30" disabled={form.lignes.length===1} on:click={()=>removeLine(i)}>×</button></div>{/each}</div><div class="mt-4 flex justify-end"><div class="rounded-xl bg-slate-50 px-5 py-3 text-right dark:bg-slate-800"><span class="text-sm text-slate-500">Total HT</span><p class="text-2xl font-extrabold">{money(total)}</p></div></div></div>
 <label class="mt-5 block"><span class="label">Notes</span><textarea class="input min-h-24" bind:value={form.notes} placeholder="Informations de livraison, référence fournisseur…"></textarea></label>
 {#if message}<p class="mt-3 rounded-lg bg-red-50 p-3 text-sm text-red-700">{message}</p>{/if}<div class="mt-6 flex justify-end gap-3"><button class="btn-secondary" on:click={()=>open=false}>Annuler</button><button class="btn-primary" disabled={saving} on:click={save}>{saving?'Enregistrement…':editing?'Enregistrer':'Créer la commande'}</button></div>
 </div></div>{/if}
<style>.input{width:100%;border:1px solid #e2e8f0;border-radius:.75rem;padding:.7rem .8rem;background:inherit;outline:none}.label{display:block;margin-bottom:.4rem;font-size:.8rem;font-weight:700;color:#64748b}:global(.dark) .input{border-color:#334155;background:#0f172a}</style>